	private function neoseo_admin_quick_links() {
		$output = '';
		$settings = $this->config->get('neoseo_admin_quick_links_' . $this->user->getID());
		if (!$settings) {
			$settings = $this->config->get('neoseo_admin_quick_links');
		}

		if (!$settings) {
		 return false;
		}

		$sort_order = array();
		if (isset($settings['quick_links'])) {
			foreach ($settings['quick_links'] as $key => $row) 
				$sort_order[$key] = $row['sort_order'];

			array_multisort($sort_order, SORT_ASC, $settings['quick_links']);

			if (count($settings['quick_links'])>0) {
				foreach ($settings['quick_links'] as $key => $item) {
						$title = $item['title'];
						$target = (isset($item['new_window']) && $item['new_window'])?'target="_blank"':'';
						$url = $this->url->link($item['route'], 'token=' . $this->session->data['token'], 'SSL');
						$icon = $item['icon'];
						$output .= sprintf('<li id="item-%s"><a data-toggle="tooltip"  title="%s" href="%s" %s><i class="fa fa-%s fa-lg"></i></a></li>',
										$key,
										$title,
										$url,
										$target,
										$icon
										);
						$output .= (isset($item['color']) && $item['color'])?
							sprintf('<style>ul#admin-quick-links li#item-%s a{background-color: #%s;}ul#admin-quick-links li#item-%s a:hover{background-color: #eee;color: #%s;}</style>', 
								$key, 
								$item['color'], 
								$key, 
								$item['color']
							):
							'';
				}
			}
		}
		return $output;
}
